<script setup>
import { computed, nextTick, ref } from 'vue';
import Dialog from './Dialog.vue';
import { calendarCells, wibNow } from '../../Support/calendar.js';
const props = defineProps({ label: String, name: String, error: String, timeOnly: Boolean, disabled: Boolean });
const model = defineModel();
const open = ref(false); const selected = ref(''); const hour = ref('00'); const minute = ref('00'); const year = ref(2026); const month = ref(0);
const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const cells = computed(() => calendarCells(year.value, month.value));
const years = computed(() => Array.from({ length: 11 }, (_, i) => year.value - 5 + i));
const display = computed(() => props.timeOnly ? `${model.value || '--:--'} WIB` : model.value ? new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(`${model.value}:00Z`)) + ` · ${model.value.slice(11, 16)} WIB` : 'Choose date & time');
const begin = () => { const value = props.timeOnly ? `2026-01-01T${model.value || '08:00'}` : model.value || wibNow(); selected.value = value.slice(0, 10); hour.value = value.slice(11, 13); minute.value = value.slice(14, 16); year.value = Number(value.slice(0, 4)); month.value = Number(value.slice(5, 7)) - 1; open.value = true; };
const navigate = (amount) => { const next = new Date(Date.UTC(year.value, month.value + amount, 1)); year.value = next.getUTCFullYear(); month.value = next.getUTCMonth(); };
const choose = (cell) => { selected.value = cell.key; year.value = Number(cell.key.slice(0, 4)); month.value = Number(cell.key.slice(5, 7)) - 1; };
const today = () => { const now = wibNow(); selected.value = now.slice(0, 10); year.value = Number(now.slice(0, 4)); month.value = Number(now.slice(5, 7)) - 1; };
const move = async (event, cell) => { const offsets = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }; if (!(event.key in offsets)) return; event.preventDefault(); const date = new Date(`${cell.key}T00:00:00Z`); date.setUTCDate(date.getUTCDate() + offsets[event.key]); choose({ key: date.toISOString().slice(0, 10) }); await nextTick(); document.getElementById(`${props.name}-${selected.value}`)?.focus(); };
const apply = () => { model.value = props.timeOnly ? `${hour.value}:${minute.value}` : `${selected.value}T${hour.value}:${minute.value}`; open.value = false; };
</script>
<template>
    <div><label :for="name" class="text-sm font-medium">{{ label }}</label><button :id="name" type="button" :disabled="disabled" :aria-invalid="Boolean(error)" class="disabled:opacity-40 mt-2 flex min-h-14 w-full items-center justify-between gap-3 rounded-2xl border border-stone-300 bg-white px-4 py-3 text-left text-sm transition-colors hover:border-stone-500 focus-visible:outline-2 focus-visible:outline-stone-600" @click="begin"><span :class="!model ? 'text-stone-400' : ''">{{ display }}</span><svg aria-hidden="true" viewBox="0 0 24 24" class="size-5 shrink-0 text-stone-500" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18"/></svg></button><p v-if="error" role="alert" class="mt-2 text-sm text-red-700">{{ error }}</p></div>
    <Dialog :open="open" :title="label" @close="open = false"><div v-if="!timeOnly" class="flex items-center justify-between gap-3"><button type="button" aria-label="Previous month" class="flex size-9 items-center justify-center rounded-full border border-stone-200 hover:bg-stone-100" @click="navigate(-1)">‹</button><div class="flex gap-2"><select v-model.number="month" aria-label="Month" class="rounded-lg border border-stone-200 bg-stone-50 px-2 py-2 text-sm font-medium"><option v-for="(name, index) in months" :key="name" :value="index">{{ name }}</option></select><select v-model.number="year" aria-label="Year" class="rounded-lg border border-stone-200 bg-stone-50 px-2 py-2 text-sm"><option v-for="value in years" :key="value" :value="value">{{ value }}</option></select></div><button type="button" aria-label="Next month" class="flex size-9 items-center justify-center rounded-full border border-stone-200 hover:bg-stone-100" @click="navigate(1)">›</button></div>
        <div v-if="!timeOnly" class="mt-5 grid grid-cols-7 gap-1 text-center text-xs text-stone-400"><span v-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day" class="py-2">{{ day }}</span><button v-for="cell in cells" :id="`${name}-${cell.key}`" :key="cell.key" type="button" :aria-label="cell.key" :aria-pressed="selected === cell.key" :tabindex="selected === cell.key ? 0 : -1" class="aspect-square rounded-xl text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-stone-600" :class="selected === cell.key ? 'bg-[#504941] text-white shadow-sm' : cell.key === wibNow().slice(0,10) ? 'bg-[#edf2e7] text-[#60734c]' : cell.currentMonth ? 'text-stone-700 hover:bg-stone-100' : 'text-stone-300 hover:bg-stone-50'" @click="choose(cell)" @keydown="move($event, cell)">{{ cell.day }}</button></div>
        <div class="mt-5 flex flex-wrap items-center justify-between gap-3 border-t border-stone-100 pt-5"><span class="text-sm font-medium text-stone-600">Time · WIB</span><div class="flex items-center gap-2"><select v-model="hour" aria-label="Hour" class="rounded-xl border border-stone-200 bg-stone-50 px-3 py-2 text-lg font-semibold tabular-nums"><option v-for="h in 24" :key="h" :value="String(h-1).padStart(2,'0')">{{ String(h-1).padStart(2,'0') }}</option></select><span>:</span><select v-model="minute" aria-label="Minute" class="rounded-xl border border-stone-200 bg-stone-50 px-3 py-2 text-lg font-semibold tabular-nums"><option v-for="m in 60" :key="m" :value="String(m-1).padStart(2,'0')">{{ String(m-1).padStart(2,'0') }}</option></select></div></div><div class="mt-5 flex items-center justify-between"><button v-if="!timeOnly" type="button" class="text-sm text-stone-500 underline" @click="today">Today</button><button type="button" class="rounded-full bg-[#504941] px-5 py-3 text-sm font-medium text-white" @click="apply">{{ timeOnly ? 'Apply time' : 'Apply date & time' }}</button></div>
    </Dialog>
</template>
